<script>
 import { onMount } from 'svelte'; import { Link2, ArrowLeft, Pencil, ImagePlus, Plus, Trash2, ExternalLink } from 'lucide-svelte';
 import Modal from '../../../components/Modal.svelte'; import ChangeModal from '../modals/ChangeModal.svelte'; import ChangeCoverModal from '../modals/ChangeCoverModal.svelte'; import ItemModal from '../modals/ItemModal.svelte';
 import { getLinkTree, updateLinkTree, uploadLinkTreeCover, createLinkTreeItem, updateLinkTreeItem, deleteLinkTreeItem, deleteLinkTree } from '../api/linkTreeApi.js';
 import { setCurrentLinkTree } from '../states/linkTreesStore.js'; import { confirmDialog, showErrorDialog, showSuccessDialog } from '../../../helpers/toolsHelper.js'; import { navigate } from '../../../router.js';
 let { id }=$props(); let item=$state(null); let loading=$state(true); let modal=$state(''); let editingItem=$state(null);
 async function load(){loading=true;try{const r=await getLinkTree(id);item=r.data?.link_tree||null;setCurrentLinkTree(item)}catch(e){await showErrorDialog(e.message)}finally{loading=false}}
 onMount(load);
 async function update(data){try{await updateLinkTree(id,data);modal='';await load();await showSuccessDialog('Data Link Tree diperbarui.')}catch(e){await showErrorDialog(e.message)}}
 async function cover(file){try{await uploadLinkTreeCover(id,file);modal='';await load();await showSuccessDialog('Sampul diperbarui.')}catch(e){await showErrorDialog(e.message)}}
 async function saveItem(data){try{if(editingItem)await updateLinkTreeItem(id,editingItem.id,data);else await createLinkTreeItem(id,data);modal='';editingItem=null;await load();await showSuccessDialog('Tautan tersimpan.')}catch(e){await showErrorDialog(e.message)}}
 async function removeItem(link){if(!await confirmDialog(`Hapus tautan "${link.title}"?`))return;try{await deleteLinkTreeItem(id,link.id);await load();await showSuccessDialog('Tautan dihapus.')}catch(e){await showErrorDialog(e.message)}}
 async function removeTree(){if(!await confirmDialog('Hapus Link Tree ini?'))return;try{await deleteLinkTree(id);navigate('/');await showSuccessDialog('Link Tree dihapus.')}catch(e){await showErrorDialog(e.message)}}
</script>
<svelte:head><title>{item?.title||'Detail Link Tree'} · Delcom Link Tree</title></svelte:head>
{#if loading}<div class="panel p-12 text-center text-slate-500">Memuat detail...</div>{:else if !item}<div class="panel p-12 text-center"><h1 class="text-2xl font-extrabold">Link Tree tidak ditemukan</h1><button class="btn btn-primary mt-4" onclick={()=>navigate('/')}>Kembali</button></div>{:else}
<button class="mb-5 flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-indigo-600" onclick={()=>navigate('/')}><ArrowLeft size={17}/> Kembali ke semua Link Tree</button>
<section class="panel overflow-hidden"><div class="relative flex min-h-48 items-end bg-gradient-to-r from-indigo-600 to-violet-500 p-7 text-white" style={item.cover_url?`background-image:linear-gradient(#1e1b4b55,#1e1b4b99),url(${item.cover_url});background-size:cover;background-position:center`:''}><div><span class="rounded-full bg-white/20 px-3 py-1 text-xs font-bold uppercase">{item.type||'public'}</span><h1 class="mt-3 text-3xl font-extrabold">{item.title}</h1><p class="mt-2 max-w-2xl text-white/85">{item.description||'Kumpulan tautan pilihan.'}</p></div></div><div class="flex flex-wrap gap-2 border-b border-slate-100 p-5"><button class="btn btn-muted" onclick={()=>modal='change'}><Pencil size={16}/> Ubah data</button><button class="btn btn-muted" onclick={()=>modal='cover'}><ImagePlus size={16}/> Ubah sampul</button><button class="btn btn-danger" onclick={removeTree}><Trash2 size={16}/> Hapus Link Tree</button></div>
<div class="p-5 sm:p-7"><div class="mb-5 flex items-center justify-between gap-3"><div><h2 class="text-xl font-extrabold">Daftar tautan</h2><p class="mt-1 text-sm text-slate-500">Kelola tautan yang ada pada halaman ini.</p></div><button class="btn btn-primary" onclick={()=>{editingItem=null;modal='item'}}><Plus size={17}/> Tambah tautan</button></div>
{#if !(item.items||[]).length}<div class="rounded-xl border border-dashed border-slate-300 py-12 text-center text-slate-500">Belum ada tautan. Tambahkan tautan pertamamu.</div>{:else}<div class="space-y-3">{#each item.items as link (link.id)}<article class="link-card"><div class="min-w-0"><h3 class="font-extrabold">{link.title}</h3><p class="mt-1 truncate text-sm text-slate-500">{link.description||link.url}</p><a class="mt-2 inline-flex items-center gap-1 break-all text-sm text-indigo-600" href={link.url} target="_blank" rel="noreferrer">{link.url}<ExternalLink size={13}/></a></div><div class="flex shrink-0 gap-1"><button class="rounded-lg p-2 text-slate-500 hover:bg-indigo-50 hover:text-indigo-600" aria-label={'Ubah '+link.title} onclick={()=>{editingItem=link;modal='item'}}><Pencil size={16}/></button><button class="rounded-lg p-2 text-slate-500 hover:bg-red-50 hover:text-red-600" aria-label={'Hapus '+link.title} onclick={()=>removeItem(link)}><Trash2 size={16}/></button></div></article>{/each}</div>{/if}</div></section>
{/if}
{#if modal==='change'}<Modal title="Ubah Link Tree" onClose={()=>modal=''}>{#snippet children()}<ChangeModal item={item} onClose={()=>modal=''} onSave={update}/>{/snippet}</Modal>{:else if modal==='cover'}<Modal title="Ubah sampul" onClose={()=>modal=''}>{#snippet children()}<ChangeCoverModal onClose={()=>modal=''} onSave={cover}/>{/snippet}</Modal>{:else if modal==='item'}<Modal title={editingItem?'Ubah tautan':'Tambah tautan'} onClose={()=>{modal='';editingItem=null}}>{#snippet children()}<ItemModal item={editingItem} onClose={()=>{modal='';editingItem=null}} onSave={saveItem}/>{/snippet}</Modal>{/if}
